using System;

namespace InformationCMS.Controls.LandingPage
{
    /// <summary>
    /// Model Landing Page (CMS_TD_LandingPage).
    /// </summary>
    [Serializable]
    public class LandingPageModel
    {
        public int PageID { get; set; }
        public string Slug { get; set; }
        public string Title { get; set; }
        public string LayoutJson { get; set; }
        public string HtmlContent { get; set; }
        public string CssContent { get; set; }
        public bool Status { get; set; }
        public DateTime CreatedDate { get; set; }
        public DateTime UpdatedDate { get; set; }
        public string CreatedUser { get; set; }
        public string UpdatedUser { get; set; }

        public LandingPageModel()
        {
            PageID = 0;
            Slug = string.Empty;
            Title = string.Empty;
            LayoutJson = "{}";
            HtmlContent = string.Empty;
            CssContent = string.Empty;
            Status = false;
            CreatedDate = DateTime.Now;
            UpdatedDate = DateTime.Now;
            CreatedUser = string.Empty;
            UpdatedUser = string.Empty;
        }
    }

    /// <summary>
    /// Response JSON cho Handler API.
    /// </summary>
    [Serializable]
    public class LandingPageApiResult
    {
        public bool Success { get; set; }
        public string Message { get; set; }
        public object Data { get; set; }

        public LandingPageApiResult()
        {
            Success = false;
            Message = string.Empty;
            Data = null;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using InformationWebObject;

namespace InformationCMS.Controls.LandingPage
{
    /// <summary>
    /// DAL Landing Page — load stored procedure qua INFO_Information (cùng pattern các module CMS).
    /// </summary>
    public class LandingPageDAL
    {
        public DataTable Search(string strKeyword, int? intStatus)
        {
            INFO_Information objInformation = new INFO_Information();
            return objInformation.GetDataTable(
                "CMS_TD_LandingPage_SearchCMS",
                "@Keyword", string.IsNullOrEmpty(strKeyword) ? (object)DBNull.Value : strKeyword.Trim(),
                "@Status", intStatus.HasValue ? (object)intStatus.Value : DBNull.Value
            );
        }

        public DataTable GetById(int intPageID)
        {
            INFO_Information objInformation = new INFO_Information();
            return objInformation.GetDataTable(
                "CMS_TD_LandingPage_GetByID",
                "@PageID", intPageID
            );
        }

        public DataTable GetBySlug(string strSlug, bool bolPublishedOnly)
        {
            INFO_Information objInformation = new INFO_Information();
            return objInformation.GetDataTable(
                "CMS_TD_LandingPage_GetBySlug",
                "@Slug", strSlug,
                "@PublishedOnly", bolPublishedOnly ? 1 : 0
            );
        }

        public bool ExistsSlug(string strSlug, int intPageID)
        {
            INFO_Information objInformation = new INFO_Information();
            DataTable dtbData = objInformation.GetDataTable(
                "CMS_TD_LandingPage_ExistsSlug",
                "@Slug", strSlug,
                "@PageID", intPageID
            );

            if (dtbData == null || dtbData.Rows.Count < 1)
                return false;

            int intTotal = 0;
            int.TryParse(Convert.ToString(dtbData.Rows[0]["Total"]), out intTotal);
            return intTotal > 0;
        }

        public int Save(LandingPageModel objModel, string strUserName)
        {
            if (objModel == null)
                return 0;

            INFO_Information objInformation = new INFO_Information();
            DataTable dtbData = objInformation.GetDataTable(
                "CMS_TD_LandingPage_Save",
                "@PageID", objModel.PageID > 0 ? (object)objModel.PageID : DBNull.Value,
                "@Slug", objModel.Slug,
                "@Title", objModel.Title,
                "@LayoutJson", string.IsNullOrEmpty(objModel.LayoutJson) ? "{}" : objModel.LayoutJson,
                "@HtmlContent", string.IsNullOrEmpty(objModel.HtmlContent) ? (object)DBNull.Value : objModel.HtmlContent,
                "@CssContent", string.IsNullOrEmpty(objModel.CssContent) ? (object)DBNull.Value : objModel.CssContent,
                "@Status", objModel.Status ? 1 : 0,
                "@UserName", string.IsNullOrEmpty(strUserName) ? (object)DBNull.Value : strUserName
            );

            if (dtbData != null && dtbData.Rows.Count > 0 && dtbData.Columns.Contains("PageID"))
            {
                object objValue = dtbData.Rows[0]["PageID"];
                if (objValue != null && objValue != DBNull.Value)
                    return Convert.ToInt32(objValue);
            }

            return objModel.PageID;
        }

        public void Delete(int intPageID)
        {
            INFO_Information objInformation = new INFO_Information();
            objInformation.GetDataTable(
                "CMS_TD_LandingPage_Delete",
                "@PageID", intPageID
            );
        }

        public LandingPageModel MapRow(DataRow drwData)
        {
            if (drwData == null)
                return null;

            LandingPageModel objModel = new LandingPageModel();
            objModel.PageID = Convert.ToInt32(drwData["PageID"]);
            objModel.Slug = Convert.ToString(drwData["Slug"]);
            objModel.Title = Convert.ToString(drwData["Title"]);

            if (drwData.Table.Columns.Contains("LayoutJson"))
                objModel.LayoutJson = Convert.ToString(drwData["LayoutJson"]);
            if (drwData.Table.Columns.Contains("HtmlContent"))
                objModel.HtmlContent = Convert.ToString(drwData["HtmlContent"]);
            if (drwData.Table.Columns.Contains("CssContent"))
                objModel.CssContent = Convert.ToString(drwData["CssContent"]);

            if (drwData.Table.Columns.Contains("Status") && drwData["Status"] != DBNull.Value)
                objModel.Status = Convert.ToBoolean(drwData["Status"]);

            if (drwData.Table.Columns.Contains("CreatedDate") && drwData["CreatedDate"] != DBNull.Value)
                objModel.CreatedDate = Convert.ToDateTime(drwData["CreatedDate"]);
            if (drwData.Table.Columns.Contains("UpdatedDate") && drwData["UpdatedDate"] != DBNull.Value)
                objModel.UpdatedDate = Convert.ToDateTime(drwData["UpdatedDate"]);

            if (drwData.Table.Columns.Contains("CreatedUser"))
                objModel.CreatedUser = Convert.ToString(drwData["CreatedUser"]);
            if (drwData.Table.Columns.Contains("UpdatedUser"))
                objModel.UpdatedUser = Convert.ToString(drwData["UpdatedUser"]);

            return objModel;
        }

        public LandingPageModel GetModelById(int intPageID)
        {
            DataTable dtbData = GetById(intPageID);
            if (dtbData == null || dtbData.Rows.Count < 1)
                return null;
            return MapRow(dtbData.Rows[0]);
        }

        public LandingPageModel GetModelBySlug(string strSlug, bool bolPublishedOnly)
        {
            DataTable dtbData = GetBySlug(strSlug, bolPublishedOnly);
            if (dtbData == null || dtbData.Rows.Count < 1)
                return null;
            return MapRow(dtbData.Rows[0]);
        }

        public List<LandingPageModel> GetList(string strKeyword, int? intStatus)
        {
            List<LandingPageModel> lstResult = new List<LandingPageModel>();
            DataTable dtbData = Search(strKeyword, intStatus);
            if (dtbData == null)
                return lstResult;

            for (int i = 0; i < dtbData.Rows.Count; i++)
            {
                LandingPageModel objModel = MapRow(dtbData.Rows[i]);
                if (objModel != null)
                    lstResult.Add(objModel);
            }
            return lstResult;
        }
    }
}

using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using System.Web;
using System.Web.Script.Serialization;
using System.Web.SessionState;
using DCore;

namespace InformationCMS.Controls.LandingPage
{
    /// <summary>
    /// API Landing Page: SavePage, GetPage, GetPageBySlug, GetPageList, DeletePage
    /// </summary>
    public class LandingPageHandler : IHttpHandler, IRequiresSessionState
    {
        public void ProcessRequest(HttpContext context)
        {
            context.Response.ContentType = "application/json; charset=utf-8";
            context.Response.AppendHeader("Cache-Control", "no-cache");

            string strAction = context.Request["action"];
            if (string.IsNullOrEmpty(strAction))
                strAction = context.Request.QueryString["action"];

            try
            {
                if (string.IsNullOrEmpty(strAction))
                {
                    WriteResult(context, false, "Thieu action", null);
                    return;
                }

                strAction = strAction.Trim().ToLowerInvariant();

                // GetPageBySlug: public (chi page publish). Con lai bat buoc dang nhap.
                if (strAction != "getpagebyslug" && !IsAdminLoggedIn(context))
                {
                    context.Response.StatusCode = 401;
                    WriteResult(context, false, "Ban chua dang nhap hoac khong co quyen", null);
                    return;
                }

                switch (strAction)
                {
                    case "savepage":
                        HandleSavePage(context);
                        break;
                    case "getpage":
                        HandleGetPage(context);
                        break;
                    case "getpagebyslug":
                        HandleGetPageBySlug(context);
                        break;
                    case "getpagelist":
                        HandleGetPageList(context);
                        break;
                    case "deletepage":
                        HandleDeletePage(context);
                        break;
                    default:
                        WriteResult(context, false, "Action khong hop le", null);
                        break;
                }
            }
            catch (Exception ex)
            {
                try
                {
                    System.Diagnostics.Debug.WriteLine("LandingPageHandler: " + ex.ToString());
                }
                catch
                {
                }

                WriteResult(context, false, "Loi he thong. Vui long thu lai.", null);
            }
        }

        private void HandleSavePage(HttpContext context)
        {
            string strBody = ReadRequestBody(context);
            if (string.IsNullOrEmpty(strBody))
            {
                WriteResult(context, false, "Body rong", null);
                return;
            }

            JavaScriptSerializer objSerializer = CreateSerializer();
            LandingPageModel objModel = objSerializer.Deserialize<LandingPageModel>(strBody);
            if (objModel == null)
            {
                WriteResult(context, false, "JSON khong hop le", null);
                return;
            }

            objModel.Title = (objModel.Title ?? string.Empty).Trim();
            objModel.Slug = NormalizeSlug(objModel.Slug);

            if (string.IsNullOrEmpty(objModel.Title))
            {
                WriteResult(context, false, "Title bat buoc", null);
                return;
            }
            if (string.IsNullOrEmpty(objModel.Slug))
            {
                WriteResult(context, false, "Slug bat buoc", null);
                return;
            }
            if (!IsValidSlug(objModel.Slug))
            {
                WriteResult(context, false, "Slug chi gom a-z, 0-9, dau gach ngang", null);
                return;
            }

            LandingPageDAL objDal = new LandingPageDAL();
            if (objDal.ExistsSlug(objModel.Slug, objModel.PageID))
            {
                WriteResult(context, false, "Slug da ton tai, vui long doi slug khac", null);
                return;
            }

            if (string.IsNullOrEmpty(objModel.LayoutJson))
                objModel.LayoutJson = "{}";

            SessionUser objUser = context.Session[Globals.USER] as SessionUser;
            string strUserName = objUser != null ? objUser.UserName : string.Empty;

            int intPageID = objDal.Save(objModel, strUserName);
            WriteResult(context, true, "Luu thanh cong", new { PageID = intPageID, Slug = objModel.Slug, Status = objModel.Status });
        }

        private void HandleGetPage(HttpContext context)
        {
            int intPageID = 0;
            int.TryParse(context.Request["PageID"], out intPageID);
            if (intPageID < 1)
            {
                WriteResult(context, false, "PageID khong hop le", null);
                return;
            }

            LandingPageDAL objDal = new LandingPageDAL();
            LandingPageModel objModel = objDal.GetModelById(intPageID);
            if (objModel == null)
            {
                WriteResult(context, false, "Khong tim thay page", null);
                return;
            }

            WriteResult(context, true, "OK", objModel);
        }

        private void HandleGetPageBySlug(HttpContext context)
        {
            string strSlug = NormalizeSlug(context.Request["Slug"]);
            if (string.IsNullOrEmpty(strSlug))
            {
                WriteResult(context, false, "Slug khong hop le", null);
                return;
            }

            bool bolPreview = false;
            string strPreview = context.Request["preview"];
            if (!string.IsNullOrEmpty(strPreview) && (strPreview == "1" || strPreview.Equals("true", StringComparison.OrdinalIgnoreCase)))
                bolPreview = IsAdminLoggedIn(context);

            LandingPageDAL objDal = new LandingPageDAL();
            LandingPageModel objModel = objDal.GetModelBySlug(strSlug, !bolPreview);
            if (objModel == null)
            {
                WriteResult(context, false, "Khong tim thay page", null);
                return;
            }

            WriteResult(context, true, "OK", objModel);
        }

        private void HandleGetPageList(HttpContext context)
        {
            string strKeyword = context.Request["Keyword"];
            int? intStatus = null;
            int intTemp = 0;
            if (!string.IsNullOrEmpty(context.Request["Status"]) && int.TryParse(context.Request["Status"], out intTemp))
                intStatus = intTemp;

            LandingPageDAL objDal = new LandingPageDAL();
            WriteResult(context, true, "OK", objDal.GetList(strKeyword, intStatus));
        }

        private void HandleDeletePage(HttpContext context)
        {
            int intPageID = 0;
            int.TryParse(context.Request["PageID"], out intPageID);
            if (intPageID < 1)
            {
                string strBody = ReadRequestBody(context);
                if (!string.IsNullOrEmpty(strBody))
                {
                    JavaScriptSerializer objSerializer = CreateSerializer();
                    LandingPageModel objTemp = objSerializer.Deserialize<LandingPageModel>(strBody);
                    if (objTemp != null)
                        intPageID = objTemp.PageID;
                }
            }

            if (intPageID < 1)
            {
                WriteResult(context, false, "PageID khong hop le", null);
                return;
            }

            LandingPageDAL objDal = new LandingPageDAL();
            objDal.Delete(intPageID);
            WriteResult(context, true, "Da xoa Landing Page", null);
        }

        private static bool IsAdminLoggedIn(HttpContext context)
        {
            if (context == null || context.Session == null)
                return false;

            SessionUser objUser = context.Session[Globals.USER] as SessionUser;
            return objUser != null && !string.IsNullOrEmpty(objUser.UserName);
        }

        private static string ReadRequestBody(HttpContext context)
        {
            if (context.Request.InputStream == null)
                return string.Empty;

            context.Request.InputStream.Position = 0;
            using (StreamReader objReader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
            {
                return objReader.ReadToEnd();
            }
        }

        private static JavaScriptSerializer CreateSerializer()
        {
            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            objSerializer.MaxJsonLength = int.MaxValue;
            return objSerializer;
        }

        private static void WriteResult(HttpContext context, bool bolSuccess, string strMessage, object objData)
        {
            LandingPageApiResult objResult = new LandingPageApiResult();
            objResult.Success = bolSuccess;
            objResult.Message = strMessage;
            objResult.Data = objData;

            JavaScriptSerializer objSerializer = CreateSerializer();
            context.Response.Write(objSerializer.Serialize(objResult));
        }

        public static string NormalizeSlug(string strSlug)
        {
            if (string.IsNullOrEmpty(strSlug))
                return string.Empty;

            strSlug = strSlug.Trim().ToLowerInvariant();
            strSlug = strSlug.Replace(" ", "-");
            strSlug = Regex.Replace(strSlug, @"[^a-z0-9\-]", "");
            strSlug = Regex.Replace(strSlug, @"\-+", "-");
            strSlug = strSlug.Trim('-');
            return strSlug;
        }

        public static bool IsValidSlug(string strSlug)
        {
            if (string.IsNullOrEmpty(strSlug))
                return false;
            return Regex.IsMatch(strSlug, @"^[a-z0-9]+(?:-[a-z0-9]+)*$");
        }

        /// <summary>
        /// Loai bo script/event handler co ban khi render HTML public.
        /// </summary>
        public static string SanitizeHtml(string strHtml)
        {
            if (string.IsNullOrEmpty(strHtml))
                return string.Empty;

            string strResult = strHtml;
            strResult = Regex.Replace(strResult, @"<script[\s\S]*?</script>", string.Empty, RegexOptions.IgnoreCase);
            strResult = Regex.Replace(strResult, @"<iframe[\s\S]*?</iframe>", string.Empty, RegexOptions.IgnoreCase);
            strResult = Regex.Replace(strResult, @"\son\w+\s*=\s*(""[^""]*""|'[^']*'|[^\s>]+)", string.Empty, RegexOptions.IgnoreCase);
            strResult = Regex.Replace(strResult, @"javascript\s*:", string.Empty, RegexOptions.IgnoreCase);
            return strResult;
        }

        public bool IsReusable
        {
            get { return false; }
        }
    }
}

using System;
