namespace InformationCMS.Controls.LandingPage
{
    public partial class List : ControlBase
    {
        private const int PageSize = 20;
        private const string BuilderPage = "~/Pages/0.LandingPage/PageBuilder.aspx";

        protected String strPermissionView = "CMS_LandingPage_View";
        protected String strPermissionAddEdit = "CMS_LandingPage_AddEdit";
        protected String strPermissionDelete = "CMS_LandingPage_Delete";

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                SetPermission();
                GridDatabind(0);
            }
        }

        private void SetPermission()
        {
            btnAddNew.Visible = true;
        }

        private void GridDatabind(int intPageIndex)
        {
            int? intStatus = null;
            if (!string.IsNullOrEmpty(ddlStatus.SelectedValue))
                intStatus = Convert.ToInt32(ddlStatus.SelectedValue);

            LandingPageDAL objDal = new LandingPageDAL();
            DataTable dtbData = objDal.Search(txtSearch.Text.Trim(), intStatus);

            grvObject.PageSize = PageSize;
            grvObject.PageIndex = intPageIndex;
            grvObject.DataSource = dtbData;
            grvObject.DataBind();
            udpList.Update();
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            GridDatabind(0);
        }

        protected void grvObject_RowCreated(object sender, GridViewRowEventArgs e)
        {
            if (e.Row.RowType == DataControlRowType.Header)
                e.Row.CssClass = "lp-thead";
        }

        protected void grvObject_PageIndexChanging(object sender, GridViewPageEventArgs e)
        {
            GridDatabind(e.NewPageIndex);
        }

        protected void lbtEdit_Click(object sender, EventArgs e)
        {
            LinkButton lbtTemp = sender as LinkButton;
            if (lbtTemp == null)
                return;

            Response.Redirect(ResolveUrl(BuilderPage) + "?id=" + lbtTemp.CommandArgument);
        }

        protected void btnAddNew_Click(object sender, EventArgs e)
        {
            Response.Redirect(ResolveUrl(BuilderPage));
        }

        protected void lbtDelete_Click(object sender, EventArgs e)
        {
            LinkButton lbtTemp = sender as LinkButton;
            if (lbtTemp == null)
                return;

            int intPageID = 0;
            int.TryParse(lbtTemp.CommandArgument, out intPageID);
            if (intPageID < 1)
                return;

            LandingPageDAL objDal = new LandingPageDAL();
            objDal.Delete(intPageID);

            MsgBox.ShowSuccess("Đã xóa Landing Page");
            GridDatabind(grvObject.PageIndex);
        }
    }
}

