    }

    function initEditor() {
        editor = grapesjs.init({
            container: '#gjs',
            height: '100%',
            width: 'auto',
            fromElement: false,
            storageManager: false,
            noticeOnUnload: false,
            canvas: {
                styles: [
                    'https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css'
                ]
            },
            deviceManager: {
                devices: [
                    { name: 'Desktop', width: '' },
                    { name: 'Tablet', width: '768px', widthMedia: '992px' },
                    { name: 'Mobile', width: '375px', widthMedia: '480px' }
                ]
            }
        });

        registerBlocks(editor);
        return editor;
    }

    function ajaxJson(url, method, body, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open(method || 'GET', url, true);
        xhr.setRequestHeader('Content-Type', 'application/json; charset=utf-8');
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) return;
            var result = null;
            try {
                result = JSON.parse(xhr.responseText || '{}');
            } catch (ex) {
                result = { Success: false, Message: 'Phản hồi không hợp lệ' };
            }
            if (typeof callback === 'function') {
                callback(result, xhr.status);
            }
        };
        xhr.send(body ? JSON.stringify(body) : null);
    }

    document.addEventListener('DOMContentLoaded', function () {
        if (typeof Vue === 'undefined' || typeof grapesjs === 'undefined') {
            alert('Không tải được VueJS hoặc GrapesJS (CDN). Kiểm tra kết nối mạng.');
            return;
        }

        initEditor();

        new Vue({
            el: '#lp-builder-app',
            data: {
                pageId: config.pageId || 0,
                title: config.initialTitle || 'Landing Page mới',
                slug: config.initialSlug || '',
                status: false,
                saving: false,
                toastVisible: false,
                toastOk: true,
                toastMessage: '',
                toastTimer: null
            },
            mounted: function () {
                var self = this;
                if (!self.slug && self.title) {
                    self.slug = slugify(self.title);
                }
                if (self.pageId > 0) {
                    self.loadPage();
                } else {
                    editor.setComponents(
                        '<section style="padding:60px 24px;text-align:center;background:#eef5fb;">' +
                        '<h1 style="color:#00519B;">Bắt đầu thiết kế Landing Page</h1>' +
                        '<p>Kéo các block từ panel bên trái vào đây.</p>' +
                        '</section>'
                    );
                }
            },
            watch: {
                title: function (val) {
                    if (!this.pageId || !this.slug) {
                        this.slug = slugify(val);
                    }
                }
            },
            methods: {
                showToast: function (msg, ok) {
                    var self = this;
                    self.toastMessage = msg;
                    self.toastOk = !!ok;
                    self.toastVisible = true;
                    if (self.toastTimer) clearTimeout(self.toastTimer);
                    self.toastTimer = setTimeout(function () {
                        self.toastVisible = false;
                    }, 2800);
                },
                loadPage: function () {
                    var self = this;
                    var url = config.handlerUrl + '?action=GetPage&PageID=' + encodeURIComponent(self.pageId);
                    ajaxJson(url, 'GET', null, function (res) {
                        if (!res || !res.Success || !res.Data) {
                            self.showToast((res && res.Message) || 'Không tải được page', false);
                            return;
                        }
                        var data = res.Data;
                        self.title = data.Title || self.title;
                        self.slug = data.Slug || self.slug;
                        self.status = !!data.Status;
                        try {
                            if (data.LayoutJson) {
                                var project = typeof data.LayoutJson === 'string' ? JSON.parse(data.LayoutJson) : data.LayoutJson;
                                editor.loadProjectData(project);
                            }
                        } catch (ex) {
                            if (data.HtmlContent) {
                                editor.setComponents(data.HtmlContent);
                            }
                            if (data.CssContent) {
                                editor.setStyle(data.CssContent);
                            }
                        }
                    });
                },
                buildPayload: function (publish) {
                    var projectData = editor.getProjectData();
                    return {
                        PageID: this.pageId || 0,
                        Title: (this.title || '').trim(),
                        Slug: slugify(this.slug || this.title || ''),
                        LayoutJson: JSON.stringify(projectData),
                        HtmlContent: editor.getHtml(),
                        CssContent: editor.getCss(),
                        Status: !!publish
                    };
                },
                save: function (publish) {
                    var self = this;
                    var payload = self.buildPayload(publish);

                    if (!payload.Title) {
                        self.showToast('Vui lòng nhập tiêu đề', false);
                        return;
                    }
                    if (!payload.Slug) {
                        self.showToast('Vui lòng nhập slug', false);
                        return;
                    }

                    self.saving = true;
                    self.slug = payload.Slug;
                    self.status = payload.Status;

                    ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                        self.saving = false;
                        if (!res || !res.Success) {
                            self.showToast((res && res.Message) || 'Lưu thất bại', false);
                            return;
                        }
                        if (res.Data && res.Data.PageID) {
                            self.pageId = res.Data.PageID;
                            if (window.history && window.history.replaceState) {
                                window.history.replaceState(null, '', '?id=' + self.pageId);
                            }
                        }
                        self.showToast(publish ? 'Đã Publish' : 'Đã lưu Draft', true);
                    });
                },
                saveDraft: function () {
                    this.save(false);
                },
                publish: function () {
                    this.save(true);
                },
                preview: function () {
                    var self = this;
                    if (!self.slug) {
                        self.showToast('Cần có slug để preview', false);
                        return;
                    }
                    // Lưu draft trước rồi mở preview
                    var payload = self.buildPayload(false);
                    self.saving = true;
                    ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                        self.saving = false;
                        if (!res || !res.Success) {
                            self.showToast((res && res.Message) || 'Không lưu được để preview', false);
                            return;
                        }
                        if (res.Data && res.Data.PageID) {
                            self.pageId = res.Data.PageID;
                        }
                        var url = config.viewUrl + '?slug=' + encodeURIComponent(self.slug) + '&preview=1';
                        window.open(url, '_blank');
                    });
                }
            }
        });
    });
})();

