            strResult = System.Text.RegularExpressions.Regex.Replace(
                strResult, @"expression\s*\(", "blocked(", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            strResult = System.Text.RegularExpressions.Regex.Replace(
                strResult, @"javascript\s*:", string.Empty, System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            strResult = strResult.Replace("</style>", string.Empty);
            return strResult;
        }
    }
