/// <summary>
/// Loai bo script/event handler co ban khi render HTML public.
/// Cho phep iframe YouTube/Vimeo (block Video).
/// </summary>
public static string SanitizeHtml(string strHtml)
{
    if (string.IsNullOrEmpty(strHtml))
        return string.Empty;

    string strResult = strHtml;
    strResult = Regex.Replace(strResult, @"<script[\s\S]*?</script>", string.Empty, RegexOptions.IgnoreCase);
    strResult = Regex.Replace(strResult, @"\son\w+\s*=\s*(""[^""]*""|'[^']*'|[^\s>]+)", string.Empty, RegexOptions.IgnoreCase);
    strResult = Regex.Replace(strResult, @"javascript\s*:", string.Empty, RegexOptions.IgnoreCase);

    // Loai iframe khong phai youtube/vimeo
    strResult = Regex.Replace(
        strResult,
        @"<iframe\b[^>]*>[\s\S]*?</iframe>",
        new MatchEvaluator(KeepSafeIframe),
        RegexOptions.IgnoreCase);

    return strResult;
}

private static string KeepSafeIframe(Match match)
{
    if (match == null)
        return string.Empty;

    string strTag = match.Value;
    string strLower = strTag.ToLowerInvariant();
    if (strLower.IndexOf("youtube.com") >= 0
        || strLower.IndexOf("youtu.be") >= 0
        || strLower.IndexOf("vimeo.com") >= 0)
    {
        return strTag;
    }
    return string.Empty;
}

