                    '<h3 style="margin:0 0 16px;color:#00519B;">Đăng ký tư vấn</h3>' +
                    '<div style="margin-bottom:12px;"><label style="display:block;margin-bottom:4px;">Họ tên</label><input type="text" name="fullname" style="width:100%;padding:10px;border:1px solid #ced4da;border-radius:4px;box-sizing:border-box;"/></div>' +
