    function openBlocksPanel(ed) {
        try {
            var btn = ed.Panels.getButton('views', 'open-blocks');
            if (btn) {
                btn.set('active', true);
            }
        } catch (ex) { }

        try {
            ed.BlockManager.render();
        } catch (ex2) { }
    }

    function setWelcomeContent(ed) {
        ed.setComponents(
            '<section style="padding:60px 24px;text-align:center;background:#eef5fb;min-height:180px;">' +
            '<h1 style="color:#00519B;margin:0 0 8px;">Bắt đầu thiết kế Landing Page</h1>' +
            '<p style="margin:0;color:#334155;">Kéo các block từ panel <strong>bên phải</strong> (icon lưới) vào đây.</p>' +
            '</section>'
        );
    }

    function initEditor() {
        var el = document.getElementById('gjs');
        if (!el) {
            alert('Không tìm thấy #gjs');
            return null;
        }

        editor = grapesjs.init({
            container: '#gjs',
            height: '100%',
            width: 'auto',
            fromElement: false,
            storageManager: false,
            noticeOnUnload: false,
            showOffsets: true,
            canvas: {
                styles: [
                    'https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css',
                    'https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css'
                ]
            },
            deviceManager: {
                devices: [
                    { name: 'Desktop', width: '' },
                    { name: 'Tablet', width: '768px', widthMedia: '992px' },
                    { name: 'Mobile', width: '375px', widthMedia: '480px' }
                ]
            },
            // Bảo đảm có panel Blocks
            blockManager: {
                appendTo: undefined
            }
        });

        registerBlocks(editor);
        openBlocksPanel(editor);

        // Mở lại Blocks khi load xong
        editor.on('load', function () {
            openBlocksPanel(editor);
        });

        return editor;
    }

    function ajaxJson(url, method, body, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open(method || 'GET', url, true);
        xhr.setRequestHeader('Content-Type', 'application/json; charset=utf-8');
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) return;
            var result = null;
            try {
                result = JSON.parse(xhr.responseText || '{}');
            } catch (ex) {
                result = { Success: false, Message: 'Phản hồi không hợp lệ' };
            }
            if (typeof callback === 'function') {
                callback(result, xhr.status);
            }
        };
        xhr.send(body ? JSON.stringify(body) : null);
    }

    function loadPageData(vm) {
        var url = config.handlerUrl + '?action=GetPage&PageID=' + encodeURIComponent(vm.pageId);
        ajaxJson(url, 'GET', null, function (res) {
            if (!res || !res.Success || !res.Data) {
                showToast((res && res.Message) || 'Không tải được page', false);
                setWelcomeContent(editor);
                return;
            }
            var data = res.Data;
            vm.title = data.Title || vm.title;
            vm.slug = data.Slug || vm.slug;
            vm.status = !!data.Status;
            try {
                if (data.LayoutJson) {
                    var project = typeof data.LayoutJson === 'string' ? JSON.parse(data.LayoutJson) : data.LayoutJson;
                    editor.loadProjectData(project);
                    // loadProjectData có thể ghi đè blocks — đăng ký lại
                    registerBlocks(editor);
                    openBlocksPanel(editor);
                    return;
                }
            } catch (ex) { }

            if (data.HtmlContent) {
                editor.setComponents(data.HtmlContent);
            } else {
                setWelcomeContent(editor);
            }
            if (data.CssContent) {
                editor.setStyle(data.CssContent);
            }
            registerBlocks(editor);
            openBlocksPanel(editor);
        });
    }

    document.addEventListener('DOMContentLoaded', function () {
        if (typeof Vue === 'undefined' || typeof grapesjs === 'undefined') {
            alert('Không tải được VueJS hoặc GrapesJS (CDN). Kiểm tra kết nối mạng.');
            return;
        }

        // 1) Vue chỉ gắn vào toolbar
        var vm = new Vue({
            el: '#lp-toolbar',
            data: {
                pageId: config.pageId || 0,
                title: config.initialTitle || 'Landing Page mới',
                slug: config.initialSlug || '',
                status: false,
                saving: false
            },
            watch: {
                title: function (val) {
                    if (!this.pageId || !this.slug) {
                        this.slug = slugify(val);
                    }
                }
            },
            methods: {
                buildPayload: function (publish) {
                    if (!editor) return null;
                    var projectData = editor.getProjectData();
                    return {
                        PageID: this.pageId || 0,
                        Title: (this.title || '').trim(),
                        Slug: slugify(this.slug || this.title || ''),
                        LayoutJson: JSON.stringify(projectData),
                        HtmlContent: editor.getHtml(),
                        CssContent: editor.getCss(),
                        Status: !!publish
                    };
                },
                save: function (publish) {
                    var self = this;
                    var payload = self.buildPayload(publish);
                    if (!payload) {
                        showToast('Editor chưa sẵn sàng', false);
                        return;
                    }
                    if (!payload.Title) {
                        showToast('Vui lòng nhập tiêu đề', false);
                        return;
                    }
                    if (!payload.Slug) {
                        showToast('Vui lòng nhập slug', false);
                        return;
                    }

                    self.saving = true;
                    self.slug = payload.Slug;
                    self.status = payload.Status;

                    ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                        self.saving = false;
                        if (!res || !res.Success) {
                            showToast((res && res.Message) || 'Lưu thất bại', false);
                            return;
                        }
                        if (res.Data && res.Data.PageID) {
                            self.pageId = res.Data.PageID;
                            if (window.history && window.history.replaceState) {
                                window.history.replaceState(null, '', '?id=' + self.pageId);
                            }
                        }
                        showToast(publish ? 'Đã Publish' : 'Đã lưu Draft', true);
                    });
                },
                saveDraft: function () { this.save(false); },
                publish: function () { this.save(true); },
                preview: function () {
                    var self = this;
                    if (!self.slug) {
                        showToast('Cần có slug để preview', false);
                        return;
                    }
                    var payload = self.buildPayload(false);
                    self.saving = true;
                    ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                        self.saving = false;
                        if (!res || !res.Success) {
                            showToast((res && res.Message) || 'Không lưu được để preview', false);
                            return;
                        }
                        if (res.Data && res.Data.PageID) {
                            self.pageId = res.Data.PageID;
                        }
                        var url = config.viewUrl + '?slug=' + encodeURIComponent(self.slug) + '&preview=1';
                        window.open(url, '_blank');
                    });
                }
            }
        });

        if (!vm.slug && vm.title) {
            vm.slug = slugify(vm.title);
        }

        // 2) Init GrapesJS SAU Vue, trên #gjs độc lập
        initEditor();
        if (!editor) return;

        if (vm.pageId > 0) {
            loadPageData(vm);
        } else {
            setWelcomeContent(editor);
            openBlocksPanel(editor);
        }

        // Expose để debug console nếu cần
        window.lpEditor = editor;
        window.lpVm = vm;
    });
})();

