var fs = require('fs');
var path = require('path');

var jsPath = path.join(__dirname, 'sample-ve-chung-toi.js');
var code = fs.readFileSync(jsPath, 'utf8');
var window = {};
eval(code);

var s = window.LP_SAMPLE_VE_CHUNG_TOI;
var html = s.html();
var css = s.css;

function esc(t) {
    return String(t).replace(/'/g, "''");
}

var lines = [];
lines.push('/*');
lines.push('  Seed Landing Page mau: Ve chung toi - Tam Duc');
lines.push('  Chay SAU file CMS_TD_LandingPage.sql');
lines.push('  Public URL: /Pages/0.LandingPage/LandingPage.aspx?slug=ve-chung-toi-tam-duc');
lines.push('*/');
lines.push('SET NOCOUNT ON;');
lines.push('');
lines.push("IF EXISTS (SELECT 1 FROM CMS_TD_LandingPage WHERE Slug = N've-chung-toi-tam-duc')");
lines.push('BEGIN');
lines.push('    UPDATE CMS_TD_LandingPage');
lines.push('    SET');
lines.push("        Title = N'" + esc(s.title) + "',");
lines.push("        LayoutJson = N'{}',");
lines.push("        HtmlContent = N'" + esc(html) + "',");
lines.push("        CssContent = N'" + esc(css) + "',");
lines.push('        Status = 1,');
lines.push('        UpdatedDate = GETDATE(),');
lines.push("        UpdatedUser = N'seed'");
lines.push("    WHERE Slug = N've-chung-toi-tam-duc';");
lines.push("    PRINT N'Updated sample ve-chung-toi-tam-duc';");
lines.push('END');
lines.push('ELSE');
lines.push('BEGIN');
lines.push('    INSERT INTO CMS_TD_LandingPage');
lines.push('    (');
lines.push('        Slug,');
lines.push('        Title,');
lines.push('        LayoutJson,');
lines.push('        HtmlContent,');
lines.push('        CssContent,');
lines.push('        Status,');
lines.push('        CreatedDate,');
lines.push('        UpdatedDate,');
lines.push('        CreatedUser,');
