/**
 * Landing Page Builder — UX gần Elementor/WordPress
 * - Panel block TRÁI luôn hiện
 * - Click để thêm (không chỉ kéo thả)
 * - Nhiều section mẫu
 */
(function () {
    'use strict';

    var config = window.LP_BUILDER_CONFIG || {};
    var editor = null;
    var toastTimer = null;

    function slugify(text) {
        if (!text) return '';
        var map = {
            'à': 'a', 'á': 'a', 'ạ': 'a', 'ả': 'a', 'ã': 'a', 'â': 'a', 'ầ': 'a', 'ấ': 'a', 'ậ': 'a', 'ẩ': 'a', 'ẫ': 'a', 'ă': 'a', 'ằ': 'a', 'ắ': 'a', 'ặ': 'a', 'ẳ': 'a', 'ẵ': 'a',
            'è': 'e', 'é': 'e', 'ẹ': 'e', 'ẻ': 'e', 'ẽ': 'e', 'ê': 'e', 'ề': 'e', 'ế': 'e', 'ệ': 'e', 'ể': 'e', 'ễ': 'e',
            'ì': 'i', 'í': 'i', 'ị': 'i', 'ỉ': 'i', 'ĩ': 'i',
            'ò': 'o', 'ó': 'o', 'ọ': 'o', 'ỏ': 'o', 'õ': 'o', 'ô': 'o', 'ồ': 'o', 'ố': 'o', 'ộ': 'o', 'ổ': 'o', 'ỗ': 'o', 'ơ': 'o', 'ờ': 'o', 'ớ': 'o', 'ợ': 'o', 'ở': 'o', 'ỡ': 'o',
            'ù': 'u', 'ú': 'u', 'ụ': 'u', 'ủ': 'u', 'ũ': 'u', 'ư': 'u', 'ừ': 'u', 'ứ': 'u', 'ự': 'u', 'ử': 'u', 'ữ': 'u',
            'ỳ': 'y', 'ý': 'y', 'ỵ': 'y', 'ỷ': 'y', 'ỹ': 'y', 'đ': 'd'
        };
        text = String(text).toLowerCase();
        text = text.replace(/./g, function (c) { return map[c] || c; });
        text = text.replace(/[^a-z0-9\s-]/g, '').replace(/[\s_-]+/g, '-').replace(/^-+|-+$/g, '');
        return text;
    }

    function showToast(msg, ok) {
        var el = document.getElementById('lp-toast');
        if (!el) return;
        el.className = 'lp-toast show ' + (ok ? 'ok' : 'err');
        el.innerHTML = msg || '';
        if (toastTimer) clearTimeout(toastTimer);
        toastTimer = setTimeout(function () { el.className = 'lp-toast'; }, 2600);
    }

    function cat(id, label, open) {
        return { id: id, label: label, open: open !== false };
    }

    function getBlockDefs() {
        return [
