    function registerBlocks(ed) {
        var bm = ed.BlockManager;
        try {
            var all = bm.getAll();
            if (all && all.reset) all.reset();
        } catch (ex) { }

        var defs = getBlockDefs();
        for (var i = 0; i < defs.length; i++) {
            var d = defs[i];
            bm.add(d.id, {
                label: d.label,
                media: '<span style="font-size:16px;">' + d.media + '</span>',
                category: d.category,
                content: d.content,
                select: true,
                activate: true
            });
        }
    }

    /** Click block = thêm vào cuối trang (dễ hơn kéo thả) */
    function enableClickToAdd(ed) {
        var host = document.getElementById('lp-blocks-host');
        if (!host) return;

        host.addEventListener('click', function (e) {
            var blockEl = e.target;
            while (blockEl && blockEl !== host && !blockEl.classList.contains('gjs-block')) {
                blockEl = blockEl.parentNode;
            }
            if (!blockEl || !blockEl.classList.contains('gjs-block')) return;

            // GrapesJS gắn data attribute / model
            var blockId = blockEl.getAttribute('data-block-id')
                || blockEl.getAttribute('id')
                || '';

            // Fallback: tìm theo label text
            var label = (blockEl.querySelector('.gjs-block-label') || blockEl).textContent || '';
            label = label.replace(/\s+/g, ' ').trim();

            var model = null;
            var all = ed.BlockManager.getAll();
            if (all) {
                all.each(function (b) {
                    if (model) return;
                    var id = b.getId ? b.getId() : b.id;
                    if (blockId && (blockId === id || blockId.indexOf(id) >= 0)) {
                        model = b;
                        return;
                    }
                    if (b.get('label') === label) model = b;
                });
            }

            if (!model) return;

            e.preventDefault();
            e.stopPropagation();

            var content = model.get('content');
            ed.addComponents(content);
            showToast('Đã thêm: ' + model.get('label'), true);

            // Scroll canvas xuống cuối
            try {
                var frame = ed.Canvas.getFrameEl();
                if (frame && frame.contentWindow) {
                    frame.contentWindow.scrollTo(0, 99999);
                }
            } catch (ex2) { }
        }, true);
    }

    function setWelcome(ed) {
        ed.setComponents(
            '<section style="padding:72px 24px;text-align:center;background:linear-gradient(180deg,#eef5fb,#fff);min-height:240px;">' +
            '<h1 style="color:#00519B;margin:0 0 10px;">Bắt đầu thiết kế như WordPress</h1>' +
            '<p style="color:#475569;margin:0 0 8px;">Click các block bên <strong>trái</strong> để thêm section (Hero, Giá, Form...)</p>' +
            '<p style="color:#94a3b8;margin:0;font-size:14px;">Hoặc kéo-thả block vào canvas · Double-click để sửa chữ</p>' +
            '</section>'
        );
    }

    function initEditor() {
        editor = grapesjs.init({
            container: '#gjs',
            height: '100%',
            width: 'auto',
            fromElement: false,
            storageManager: false,
            noticeOnUnload: false,
            showOffsets: true,
            canvas: {
                styles: [
                    'https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css'
                ]
            },
            panels: { defaults: [] },
            deviceManager: {
                devices: [
                    { id: 'desktop', name: 'Desktop', width: '' },
                    { id: 'tablet', name: 'Tablet', width: '768px', widthMedia: '992px' },
                    { id: 'mobile', name: 'Mobile', width: '375px', widthMedia: '480px' }
                ]
            },
            blockManager: {
                appendTo: '#lp-blocks-host'
            },
            styleManager: {
                appendTo: '#lp-styles-host',
                sectors: [
                    {
                        name: 'Chung',
                        open: true,
                        properties: ['width', 'height', 'max-width', 'min-height', 'margin', 'padding']
                    },
                    {
                        name: 'Chữ',
                        open: false,
                        properties: ['font-family', 'font-size', 'font-weight', 'letter-spacing', 'color', 'line-height', 'text-align']
                    },
                    {
                        name: 'Nền / Viền',
                        open: false,
                        properties: ['background-color', 'background', 'border-radius', 'border', 'box-shadow']
                    }
                ]
            },
            layerManager: {
                appendTo: '#lp-layers-host'
            },
            selectorManager: {
                appendTo: '#lp-styles-host'
            }
        });

        registerBlocks(editor);
        enableClickToAdd(editor);

        editor.on('load', function () {
            registerBlocks(editor);
            try { editor.BlockManager.render(); } catch (ex) { }
        });

        return editor;
    }

    function bindUi(ed) {
        function on(id, fn) {
            var el = document.getElementById(id);
            if (el) el.onclick = fn;
        }
        on('btnDeviceDesktop', function () { ed.setDevice('Desktop'); });
        on('btnDeviceTablet', function () { ed.setDevice('Tablet'); });
        on('btnDeviceMobile', function () { ed.setDevice('Mobile'); });
        on('btnClearCanvas', function () {
            if (confirm('Xóa toàn bộ nội dung trang?')) {
                ed.setComponents('');
                setWelcome(ed);
            }
        });
        on('btnAddBlank', function () {
            ed.addComponents('<section style="padding:48px 24px;min-height:120px;background:#fff;"><div style="max-width:1100px;margin:0 auto;"><p style="color:#94a3b8;text-align:center;">Section trống</p></div></section>');
            showToast('Đã thêm section trống', true);
        });

        // Tabs phải
        var tabs = document.querySelectorAll('#lp-right-tabs button');
        for (var i = 0; i < tabs.length; i++) {
            tabs[i].onclick = function () {
                var tab = this.getAttribute('data-tab');
                for (var j = 0; j < tabs.length; j++) tabs[j].className = '';
                this.className = 'active';
                document.getElementById('lp-styles-host').className = (tab === 'styles') ? 'active' : '';
                document.getElementById('lp-layers-host').className = (tab === 'layers') ? 'active' : '';
            };
        }

        // Filter block
        var filter = document.getElementById('lp-block-filter');
        if (filter) {
            filter.onkeyup = function () {
                var q = (filter.value || '').toLowerCase();
                var blocks = document.querySelectorAll('#lp-blocks-host .gjs-block');
                for (var k = 0; k < blocks.length; k++) {
                    var t = (blocks[k].textContent || '').toLowerCase();
                    blocks[k].style.display = (!q || t.indexOf(q) >= 0) ? '' : 'none';
                }
            };
        }
    }

    function ajaxJson(url, method, body, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open(method || 'GET', url, true);
        xhr.setRequestHeader('Content-Type', 'application/json; charset=utf-8');
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) return;
            var result = null;
            try { result = JSON.parse(xhr.responseText || '{}'); }
            catch (ex) { result = { Success: false, Message: 'Phản hồi không hợp lệ' }; }
            if (typeof callback === 'function') callback(result, xhr.status);
        };
        xhr.send(body ? JSON.stringify(body) : null);
    }

    function loadPageData(vm) {
        ajaxJson(config.handlerUrl + '?action=GetPage&PageID=' + encodeURIComponent(vm.pageId), 'GET', null, function (res) {
            if (!res || !res.Success || !res.Data) {
                showToast((res && res.Message) || 'Không tải được page', false);
                setWelcome(editor);
                return;
            }
            var data = res.Data;
            vm.title = data.Title || vm.title;
            vm.slug = data.Slug || vm.slug;
            vm.status = !!data.Status;
            try {
                if (data.LayoutJson) {
                    var project = typeof data.LayoutJson === 'string' ? JSON.parse(data.LayoutJson) : data.LayoutJson;
                    editor.loadProjectData(project);
                    registerBlocks(editor);
                    try { editor.BlockManager.render(); } catch (ex) { }
                    return;
                }
            } catch (ex2) { }

            if (data.HtmlContent) editor.setComponents(data.HtmlContent);
            else setWelcome(editor);
            if (data.CssContent) editor.setStyle(data.CssContent);
            registerBlocks(editor);
        });
    }

    document.addEventListener('DOMContentLoaded', function () {
        if (typeof Vue === 'undefined' || typeof grapesjs === 'undefined') {
            alert('Không tải được VueJS hoặc GrapesJS (CDN).');
            return;
        }

        var vm = new Vue({
            el: '#lp-toolbar',
            data: {
                pageId: config.pageId || 0,
                title: config.initialTitle || 'Landing Page mới',
                slug: config.initialSlug || '',
                status: false,
                saving: false
            },
            watch: {
                title: function (val) {
                    if (!this.pageId || !this.slug) this.slug = slugify(val);
                }
            },
            methods: {
                undo: function () { if (editor) editor.runCommand('core:undo'); },
                redo: function () { if (editor) editor.runCommand('core:redo'); },
                buildPayload: function (publish) {
                    if (!editor) return null;
                    return {
                        PageID: this.pageId || 0,
                        Title: (this.title || '').trim(),
                        Slug: slugify(this.slug || this.title || ''),
                        LayoutJson: JSON.stringify(editor.getProjectData()),
                        HtmlContent: editor.getHtml(),
                        CssContent: editor.getCss(),
                        Status: !!publish
                    };
                },
                save: function (publish) {
                    var self = this;
                    var payload = self.buildPayload(publish);
                    if (!payload) { showToast('Editor chưa sẵn sàng', false); return; }
                    if (!payload.Title) { showToast('Nhập tiêu đề', false); return; }
                    if (!payload.Slug) { showToast('Nhập slug', false); return; }
                    self.saving = true;
                    self.slug = payload.Slug;
                    self.status = payload.Status;
                    ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                        self.saving = false;
                        if (!res || !res.Success) {
                            showToast((res && res.Message) || 'Lưu thất bại', false);
                            return;
                        }
                        if (res.Data && res.Data.PageID) {
                            self.pageId = res.Data.PageID;
                            if (window.history && window.history.replaceState) {
                                window.history.replaceState(null, '', '?id=' + self.pageId);
                            }
                        }
                        showToast(publish ? 'Đã xuất bản' : 'Đã lưu nháp', true);
                    });
                },
                saveDraft: function () { this.save(false); },
                publish: function () { this.save(true); },
                preview: function () {
                    var self = this;
                    if (!self.slug) { showToast('Cần slug để xem trước', false); return; }
                    var payload = self.buildPayload(false);
                    self.saving = true;
                    ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                        self.saving = false;
                        if (!res || !res.Success) {
                            showToast((res && res.Message) || 'Không lưu được', false);
                            return;
                        }
                        if (res.Data && res.Data.PageID) self.pageId = res.Data.PageID;
                        window.open(config.viewUrl + '?slug=' + encodeURIComponent(self.slug) + '&preview=1', '_blank');
                    });
                }
            }
        });

        if (!vm.slug && vm.title) vm.slug = slugify(vm.title);

        initEditor();
        bindUi(editor);

        if (vm.pageId > 0) loadPageData(vm);
        else setWelcome(editor);

        window.lpEditor = editor;
        window.lpVm = vm;
    });
})();

/**
 * Page Builder UX đơn giản:
 * - Chọn mẫu trang 1 click
 * - Nút bấm thêm block (không phụ thuộc kéo-thả)
 * - Double-click sửa chữ
 */
(function () {
    'use strict';

    var config = window.LP_BUILDER_CONFIG || {};
    var editor = null;
    var toastTimer = null;
    var currentCat = 'all';

    function slugify(text) {
        if (!text) return '';
        var map = {
            'à': 'a', 'á': 'a', 'ạ': 'a', 'ả': 'a', 'ã': 'a', 'â': 'a', 'ầ': 'a', 'ấ': 'a', 'ậ': 'a', 'ẩ': 'a', 'ẫ': 'a', 'ă': 'a', 'ằ': 'a', 'ắ': 'a', 'ặ': 'a', 'ẳ': 'a', 'ẵ': 'a',
            'è': 'e', 'é': 'e', 'ẹ': 'e', 'ẻ': 'e', 'ẽ': 'e', 'ê': 'e', 'ề': 'e', 'ế': 'e', 'ệ': 'e', 'ể': 'e', 'ễ': 'e',
            'ì': 'i', 'í': 'i', 'ị': 'i', 'ỉ': 'i', 'ĩ': 'i',
            'ò': 'o', 'ó': 'o', 'ọ': 'o', 'ỏ': 'o', 'õ': 'o', 'ô': 'o', 'ồ': 'o', 'ố': 'o', 'ộ': 'o', 'ổ': 'o', 'ỗ': 'o', 'ơ': 'o', 'ờ': 'o', 'ớ': 'o', 'ợ': 'o', 'ở': 'o', 'ỡ': 'o',
            'ù': 'u', 'ú': 'u', 'ụ': 'u', 'ủ': 'u', 'ũ': 'u', 'ư': 'u', 'ừ': 'u', 'ứ': 'u', 'ự': 'u', 'ử': 'u', 'ữ': 'u',
            'ỳ': 'y', 'ý': 'y', 'ỵ': 'y', 'ỷ': 'y', 'ỹ': 'y', 'đ': 'd'
        };
        text = String(text).toLowerCase();
        text = text.replace(/./g, function (c) { return map[c] || c; });
        return text.replace(/[^a-z0-9\s-]/g, '').replace(/[\s_-]+/g, '-').replace(/^-+|-+$/g, '');
    }

