    function addHtml(html) {
        if (!editor) return;
        editor.addComponents(html);
        toast('Đã thêm vào trang', true);
        try {
            var frame = editor.Canvas.getFrameEl();
            if (frame && frame.contentWindow) frame.contentWindow.scrollTo(0, 99999);
        } catch (ex) { }
    }

    function applyTemplate(tpl) {
        if (!editor || !tpl) return;
        editor.setComponents(tpl.html());
        toast('Đã áp dụng mẫu: ' + tpl.name, true);
        hideModal();
    }

    function renderCats() {
        var host = document.getElementById('lp-cats');
        if (!host) return;
        var cats = [
            { id: 'all', label: 'Tất cả' },
            { id: 'section', label: 'Section' },
            { id: 'basic', label: 'Cơ bản' }
        ];
        host.innerHTML = '';
        for (var i = 0; i < cats.length; i++) {
            (function (c) {
                var b = document.createElement('button');
                b.type = 'button';
                b.textContent = c.label;
                b.className = (currentCat === c.id) ? 'on' : '';
                b.onclick = function () {
                    currentCat = c.id;
                    renderCats();
                    renderBlocks();
                };
                host.appendChild(b);
            })(cats[i]);
        }
    }

    function renderBlocks() {
        var host = document.getElementById('lp-block-list');
        if (!host) return;
        host.innerHTML = '';
        for (var i = 0; i < BLOCKS.length; i++) {
            var b = BLOCKS[i];
            if (currentCat !== 'all' && b.cat !== currentCat) continue;
            (function (item) {
                var btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'lp-block-btn';
                btn.innerHTML = '<div class="ico">' + item.ico + '</div><div><div class="t">' + item.title + '</div><div class="d">' + item.desc + '</div></div>';
                btn.onclick = function () {
                    addHtml(HTML[item.id]);
                };
                host.appendChild(btn);
            })(b);
        }
    }

    function showModal() {
        var m = document.getElementById('lp-modal');
        if (m) m.className = 'show';
    }
    function hideModal() {
        var m = document.getElementById('lp-modal');
        if (m) m.className = '';
    }

    function renderModal() {
        var grid = document.getElementById('lp-modal-grid');
        if (!grid) return;
        grid.innerHTML = '';
        for (var i = 0; i < TEMPLATES.length; i++) {
            (function (tpl) {
                var card = document.createElement('button');
                card.type = 'button';
                card.className = 'card';
                card.innerHTML = '<b>' + tpl.name + '</b><span style="color:#64748b;font-size:13px;">' + tpl.desc + '</span>';
                card.onclick = function () { applyTemplate(tpl); };
                grid.appendChild(card);
            })(TEMPLATES[i]);
        }
    }

    function setWelcome() {
        editor.setComponents(
            '<section style="padding:70px 24px;text-align:center;background:#fff;min-height:260px;">' +
            '<h1 style="color:#00519B;margin:0 0 10px;">Trang còn trống</h1>' +
            '<p style="color:#64748b;margin:0 0 18px;">Bấm “Chọn mẫu trang có sẵn” bên trái<br/>hoặc bấm từng block để thêm.</p>' +
            '</section>'
        );
    }

    function initEditor() {
        editor = grapesjs.init({
            container: '#gjs',
            height: '100%',
            fromElement: false,
            storageManager: false,
            noticeOnUnload: false,
            panels: { defaults: [] },
            canvas: {
                styles: ['https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css']
            },
            deviceManager: {
                devices: [
                    { name: 'Desktop', width: '' },
                    { name: 'Tablet', width: '768px', widthMedia: '992px' },
                    { name: 'Mobile', width: '375px', widthMedia: '480px' }
                ]
            },
            // Không dùng blockManager UI mặc định
            blockManager: { blocks: [] },
            styleManager: {
                appendTo: '#lp-styles',
                sectors: [{
                    name: 'Chỉnh nhanh',
                    open: true,
                    properties: ['color', 'background-color', 'font-size', 'font-weight', 'text-align', 'padding', 'margin', 'border-radius']
                }]
            }
        });

        editor.on('component:selected', function () {
            var box = document.getElementById('lp-styles');
            var help = document.getElementById('lp-help');
            if (box) box.className = 'show';
            if (help) help.style.display = 'none';
        });

        editor.on('component:deselected', function () {
            var selected = editor.getSelected();
            if (!selected) {
                var box = document.getElementById('lp-styles');
                var help = document.getElementById('lp-help');
                if (box) box.className = '';
                if (help) help.style.display = '';
            }
        });

        return editor;
    }

    function bindButtons() {
        function on(id, fn) {
            var el = document.getElementById(id);
            if (el) el.onclick = fn;
        }
        on('btnDesktop', function () { editor.setDevice('Desktop'); });
        on('btnTablet', function () { editor.setDevice('Tablet'); });
        on('btnMobile', function () { editor.setDevice('Mobile'); });
        on('btnClear', function () {
            if (confirm('Xóa hết nội dung trang?')) setWelcome();
        });
        on('btnDeleteSelected', function () {
            var sel = editor.getSelected();
            if (!sel) { toast('Hãy click chọn 1 mục trên trang trước', false); return; }
            sel.remove();
            toast('Đã xóa', true);
        });
        on('btnOpenTemplates', showModal);
        on('btnSkipTpl', hideModal);
    }

    function ajaxJson(url, method, body, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open(method || 'GET', url, true);
        xhr.setRequestHeader('Content-Type', 'application/json; charset=utf-8');
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) return;
            var result = null;
            try { result = JSON.parse(xhr.responseText || '{}'); }
            catch (ex) { result = { Success: false, Message: 'Lỗi phản hồi' }; }
            if (callback) callback(result);
        };
        xhr.send(body ? JSON.stringify(body) : null);
    }

    function loadPage(vm) {
        ajaxJson(config.handlerUrl + '?action=GetPage&PageID=' + encodeURIComponent(vm.pageId), 'GET', null, function (res) {
            if (!res || !res.Success || !res.Data) {
                setWelcome();
                showModal();
                return;
            }
            var data = res.Data;
            vm.title = data.Title || vm.title;
            vm.slug = data.Slug || vm.slug;
            vm.status = !!data.Status;
            try {
                if (data.LayoutJson) {
                    editor.loadProjectData(typeof data.LayoutJson === 'string' ? JSON.parse(data.LayoutJson) : data.LayoutJson);
                    return;
                }
            } catch (ex) { }
            if (data.HtmlContent) editor.setComponents(data.HtmlContent);
            else {
                setWelcome();
                showModal();
            }
            if (data.CssContent) editor.setStyle(data.CssContent);
        });
    }

    document.addEventListener('DOMContentLoaded', function () {
        if (typeof Vue === 'undefined' || typeof grapesjs === 'undefined') {
            alert('Không tải được thư viện (CDN). Kiểm tra mạng.');
            return;
        }

        // Vue cho 2 vùng top (toolbar + actions) — mount riêng từng phần bằng shared data
        var shared = {
            pageId: config.pageId || 0,
            title: config.initialTitle || 'Landing Page mới',
            slug: config.initialSlug || '',
            status: false,
            saving: false
        };
        if (!shared.slug && shared.title) shared.slug = slugify(shared.title);

        var methods = {
            undo: function () { if (editor) editor.runCommand('core:undo'); },
            buildPayload: function (publish) {
                if (!editor) return null;
                return {
                    PageID: this.pageId || 0,
                    Title: (this.title || '').trim(),
                    Slug: slugify(this.slug || this.title || ''),
                    LayoutJson: JSON.stringify(editor.getProjectData()),
                    HtmlContent: editor.getHtml(),
                    CssContent: editor.getCss(),
                    Status: !!publish
                };
            },
            save: function (publish) {
                var self = this;
                var payload = self.buildPayload(publish);
                if (!payload) return;
                if (!payload.Title) { toast('Nhập tên trang', false); return; }
                if (!payload.Slug) { toast('Nhập đường dẫn (slug)', false); return; }
                self.saving = true;
                self.slug = payload.Slug;
                self.status = payload.Status;
                ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                    self.saving = false;
                    if (!res || !res.Success) { toast((res && res.Message) || 'Lưu thất bại', false); return; }
                    if (res.Data && res.Data.PageID) {
                        self.pageId = res.Data.PageID;
                        if (window.history && window.history.replaceState) {
                            window.history.replaceState(null, '', '?id=' + self.pageId);
                        }
                    }
                    toast(publish ? 'Đã xuất bản' : 'Đã lưu', true);
                });
            },
            saveDraft: function () { this.save(false); },
            publish: function () { this.save(true); },
            preview: function () {
                var self = this;
                if (!self.slug) { toast('Cần slug để xem', false); return; }
                var payload = self.buildPayload(false);
                self.saving = true;
                ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                    self.saving = false;
                    if (!res || !res.Success) { toast((res && res.Message) || 'Không lưu được', false); return; }
                    if (res.Data && res.Data.PageID) self.pageId = res.Data.PageID;
                    window.open(config.viewUrl + '?slug=' + encodeURIComponent(self.slug) + '&preview=1', '_blank');
                });
            }
        };

        // Gộp toolbar + actions vào 1 Vue root ảo bằng cách mount vào lp-top
        // lp-top chứa cả 2 div — mount Vue trên #lp-top
        var topEl = document.getElementById('lp-top');
        // Đảm bảo v-model nằm trong Vue root: chuyển id
        topEl.setAttribute('id', 'lp-vue-top');

        var vm = new Vue({
            el: '#lp-vue-top',
            data: shared,
            watch: {
                title: function (v) {
                    if (!this.pageId || !this.slug) this.slug = slugify(v);
                }
            },
            methods: methods
        });

        initEditor();
        bindButtons();
        renderCats();
        renderBlocks();
        renderModal();

        if (vm.pageId > 0) loadPage(vm);
        else {
            setWelcome();
            showModal();
        }

        window.lpEditor = editor;
        window.lpVm = vm;
    });
})();

