var currentCat = 'all';
/** Vị trí chèn: null = cuối / sau mục chọn; số = index trong body (kiểu WP) */
var insertAt = null;

function slugify(text) {

function getWrapper() {
    return editor ? editor.getWrapper() : null;
}

function getTopComponents() {
    var wr = getWrapper();
    if (!wr) return [];
    return wr.components().models.slice(0);
}

function getTopLevelOf(comp) {
    if (!comp) return null;
    var wr = getWrapper();
    var cur = comp;
    while (cur && cur.parent && cur.parent() && cur.parent() !== wr) {
        cur = cur.parent();
    }
    if (cur && cur.parent && cur.parent() === wr) return cur;
    return null;
}

function setInsertAt(index) {
    insertAt = index;
    var mode = document.getElementById('lp-insert-mode');
    if (mode) {
        if (insertAt === null) {
            mode.className = '';
        } else {
            mode.className = 'on';
            mode.innerHTML = 'Đang chọn vị trí #' + (insertAt + 1) + ' — bấm 1 block bên trái để chèn vào đây';
        }
    }
    renderStructure();
}

function clearInsertAt() {
    insertAt = null;
    var mode = document.getElementById('lp-insert-mode');
    if (mode) mode.className = '';
}

function sectionLabel(comp, index) {
    var tag = (comp.get('tagName') || 'div').toLowerCase();
    var text = '';
    try {
        text = (comp.get('content') || '') + ' ' + (comp.view && comp.view.el ? (comp.view.el.innerText || '') : '');
    } catch (ex) { }
    text = String(text).replace(/\s+/g, ' ').trim();
    if (text.length > 28) text = text.substring(0, 28) + '…';
    if (!text) text = tag.toUpperCase();
    return (index + 1) + '. ' + text;
}

function renderStructure() {
    var host = document.getElementById('lp-structure');
    if (!host || !editor) return;
    host.innerHTML = '';

    var list = getTopComponents();
    var selectedTop = getTopLevelOf(editor.getSelected());

    function makeInsertBtn(atIndex) {
        var ins = document.createElement('div');
        ins.className = 'lp-ins' + (insertAt === atIndex ? ' active' : '');
        ins.innerHTML = '+ Thêm tại đây';
        ins.title = 'Chọn vị trí này rồi bấm block bên trái';
        ins.onclick = function () {
            setInsertAt(atIndex);
            toast('Đã chọn vị trí chèn. Bấm block bên trái.', true);
        };
        return ins;
    }

    host.appendChild(makeInsertBtn(0));

    for (var i = 0; i < list.length; i++) {
        (function (comp, idx) {
            var row = document.createElement('div');
            row.className = 'lp-sec' + (selectedTop === comp ? ' on' : '');

            var nm = document.createElement('div');
            nm.className = 'nm';
            nm.textContent = sectionLabel(comp, idx);
            nm.onclick = function () {
                editor.select(comp);
                // Mặc định: lần thêm tiếp theo sẽ chèn SAU mục này
                setInsertAt(idx + 1);
            };
            row.appendChild(nm);

            var up = document.createElement('button');
            up.type = 'button';
            up.className = 'mini';
            up.textContent = '↑';
            up.title = 'Đưa lên';
            up.onclick = function (e) {
                e.stopPropagation();
                moveComponent(comp, -1);
            };
            row.appendChild(up);

            var down = document.createElement('button');
            down.type = 'button';
            down.className = 'mini';
            down.textContent = '↓';
            down.title = 'Đưa xuống';
            down.onclick = function (e) {
                e.stopPropagation();
                moveComponent(comp, 1);
            };
            row.appendChild(down);

            var del = document.createElement('button');
            del.type = 'button';
            del.className = 'mini';
            del.textContent = '×';
            del.title = 'Xóa';
            del.onclick = function (e) {
                e.stopPropagation();
                comp.remove();
                clearInsertAt();
                renderStructure();
                toast('Đã xóa', true);
            };
            row.appendChild(del);

            host.appendChild(row);
            host.appendChild(makeInsertBtn(idx + 1));
        })(list[i], i);
    }
}

function moveComponent(comp, dir) {
    var wr = getWrapper();
    if (!wr || !comp) return;
    var collection = wr.components();
    var at = collection.indexOf(comp);
    if (at < 0) return;
    var to = at + dir;
    if (to < 0 || to >= collection.length) return;
    collection.remove(comp, { temporary: true });
    collection.add(comp, { at: to });
    editor.select(comp);
    clearInsertAt();
    renderStructure();
    toast(dir < 0 ? 'Đã đưa lên' : 'Đã đưa xuống', true);
}

function moveSelected(dir) {
    var top = getTopLevelOf(editor.getSelected());
    if (!top) {
        toast('Hãy chọn 1 mục trên trang (hoặc trong Cấu trúc) trước', false);
        return;
    }
    moveComponent(top, dir);
}

function addHtml(html) {
    if (!editor) return;
    var wr = getWrapper();
    var collection = wr.components();
    var at = insertAt;

    // Nếu chưa chọn vị trí: chèn sau section đang chọn, không thì cuối
    if (at === null) {
        var top = getTopLevelOf(editor.getSelected());
        if (top) {
            at = collection.indexOf(top) + 1;
        } else {
            at = collection.length;
        }
    }

    var added = collection.add(html, { at: at });
    var first = Array.isArray(added) ? added[0] : added;
    if (first) editor.select(first);

    clearInsertAt();
    renderStructure();
    toast('Đã chèn đúng vị trí', true);

    try {
        if (first && first.view && first.view.el && first.view.el.scrollIntoView) {
            first.view.el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    } catch (ex) { }
}

function applyTemplate(tpl) {
    if (!editor || !tpl) return;
    editor.setComponents(tpl.html());
    clearInsertAt();
    renderStructure();
    toast('Đã áp dụng mẫu: ' + tpl.name, true);
    hideModal();
}

