function initEditor() {
    editor = grapesjs.init({
        container: '#gjs',
        height: '100%',
        fromElement: false,
        storageManager: false,
        noticeOnUnload: false,
        panels: { defaults: [] },
        canvas: {
            styles: ['https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css']
        },
        deviceManager: {
            devices: [
                { name: 'Desktop', width: '' },
                { name: 'Tablet', width: '768px', widthMedia: '992px' },
                { name: 'Mobile', width: '375px', widthMedia: '480px' }
            ]
        },
        blockManager: { blocks: [] },
        styleManager: {
            appendTo: '#lp-styles',
            sectors: [{
                name: 'Chỉnh nhanh',
                open: true,
                properties: ['color', 'background-color', 'font-size', 'font-weight', 'text-align', 'padding', 'margin', 'border-radius']
            }]
        }
    });

    // Body nhận thả / chèn section thoải mái (không cần thẻ bọc)
    var wr = editor.getWrapper();
    wr.set({
        droppable: true,
        hoverable: true,
        stylable: ['background', 'background-color', 'padding', 'min-height']
    });

    editor.on('component:selected', function () {
        var box = document.getElementById('lp-styles');
        if (box) box.className = 'show';
        renderStructure();
    });

    editor.on('component:deselected', function () {
        if (!editor.getSelected()) {
            var box = document.getElementById('lp-styles');
            if (box) box.className = '';
        }
        renderStructure();
    });

    editor.on('component:add', function () { renderStructure(); });
    editor.on('component:remove', function () { renderStructure(); });
    editor.on('component:update', function () { renderStructure(); });
    editor.on('load', function () { renderStructure(); });

    return editor;
}

