/**
 * Landing Page Builder — UX kiểu WordPress/Elementor (KHÔNG dùng GrapesJS)
 * - Dấu + ngay trên trang để chọn vị trí
 * - Bấm widget để chèn
 * - Hover section: ↑ ↓ nhân bản xóa
 * - Sửa chữ trực tiếp (contenteditable)
 */
(function () {
    'use strict';

    var config = window.LP_BUILDER_CONFIG || {};
    var uidSeq = 1;

    function uid() {
        return 's' + (uidSeq++) + '_' + Date.now();
    }

    function slugify(text) {
        if (!text) return '';
        var map = {
            'à': 'a', 'á': 'a', 'ạ': 'a', 'ả': 'a', 'ã': 'a', 'â': 'a', 'ầ': 'a', 'ấ': 'a', 'ậ': 'a', 'ẩ': 'a', 'ẫ': 'a', 'ă': 'a', 'ằ': 'a', 'ắ': 'a', 'ặ': 'a', 'ẳ': 'a', 'ẵ': 'a',
            'è': 'e', 'é': 'e', 'ẹ': 'e', 'ẻ': 'e', 'ẽ': 'e', 'ê': 'e', 'ề': 'e', 'ế': 'e', 'ệ': 'e', 'ể': 'e', 'ễ': 'e',
            'ì': 'i', 'í': 'i', 'ị': 'i', 'ỉ': 'i', 'ĩ': 'i',
            'ò': 'o', 'ó': 'o', 'ọ': 'o', 'ỏ': 'o', 'õ': 'o', 'ô': 'o', 'ồ': 'o', 'ố': 'o', 'ộ': 'o', 'ổ': 'o', 'ỗ': 'o', 'ơ': 'o', 'ờ': 'o', 'ớ': 'o', 'ợ': 'o', 'ở': 'o', 'ỡ': 'o',
            'ù': 'u', 'ú': 'u', 'ụ': 'u', 'ủ': 'u', 'ũ': 'u', 'ư': 'u', 'ừ': 'u', 'ứ': 'u', 'ự': 'u', 'ử': 'u', 'ữ': 'u',
            'ỳ': 'y', 'ý': 'y', 'ỵ': 'y', 'ỷ': 'y', 'ỹ': 'y', 'đ': 'd'
        };
        text = String(text).toLowerCase();
        text = text.replace(/./g, function (c) { return map[c] || c; });
        return text.replace(/[^a-z0-9\s-]/g, '').replace(/[\s_-]+/g, '-').replace(/^-+|-+$/g, '');
    }

    function toast(msg, ok) {
        var el = document.getElementById('toast');
        if (!el) return;
        el.className = 'toast show ' + (ok ? 'ok' : 'err');
        el.innerHTML = msg || '';
        clearTimeout(toast._t);
        toast._t = setTimeout(function () { el.className = 'toast'; }, 2200);
    }

    function ajaxJson(url, method, body, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open(method || 'GET', url, true);
        xhr.setRequestHeader('Content-Type', 'application/json; charset=utf-8');
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) return;
            var result = null;
            try { result = JSON.parse(xhr.responseText || '{}'); }
            catch (ex) { result = { Success: false, Message: 'Lỗi phản hồi' }; }
            if (callback) callback(result);
        };
        xhr.send(body ? JSON.stringify(body) : null);
    }

    var HTML = {
        navbar: '<header style="background:#fff;border-bottom:1px solid #e2e8f0;padding:14px 24px;"><div style="max-width:1100px;margin:0 auto;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;"><strong style="color:#00519B;font-size:20px;">LOGO</strong><nav style="display:flex;gap:16px;"><a href="#" style="color:#334155;text-decoration:none;">Trang chủ</a><a href="#form" style="color:#334155;text-decoration:none;">Đăng ký</a></nav><a href="#form" style="background:#00519B;color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700;">Đặt lịch</a></div></header>',
