    };

    var WIDGETS = [
        { id: 'hero', cat: 'section', ico: '🏔', title: 'Hero Banner', desc: 'Tiêu đề lớn + nút' },
        { id: 'hero2', cat: 'section', ico: '◧', title: 'Hero 2 cột', desc: 'Chữ + ảnh' },
        { id: 'navbar', cat: 'section', ico: '☰', title: 'Menu trên', desc: 'Header' },
        { id: 'features', cat: 'section', ico: '◆', title: '3 điểm nổi bật', desc: '3 ô' },
        { id: 'about', cat: 'section', ico: 'ℹ', title: 'Giới thiệu', desc: 'About' },
        { id: 'pricing', cat: 'section', ico: '₫', title: 'Bảng giá', desc: 'Pricing' },
        { id: 'testimonial', cat: 'section', ico: '☺', title: 'Đánh giá', desc: 'Review' },
        { id: 'faq', cat: 'section', ico: '?', title: 'Hỏi đáp', desc: 'FAQ' },
        { id: 'cta', cat: 'section', ico: '!', title: 'CTA', desc: 'Kêu gọi' },
        { id: 'form', cat: 'section', ico: '✎', title: 'Form đăng ký', desc: 'Form' },
        { id: 'contact', cat: 'section', ico: '📍', title: 'Liên hệ', desc: 'Contact' },
        { id: 'footer', cat: 'section', ico: '▮', title: 'Footer', desc: 'Chân trang' },
        { id: 'heading', cat: 'basic', ico: 'H', title: 'Tiêu đề', desc: 'Heading' },
        { id: 'text', cat: 'basic', ico: 'T', title: 'Đoạn văn', desc: 'Text' },
        { id: 'button', cat: 'basic', ico: '▣', title: 'Nút bấm', desc: 'Button' },
        { id: 'image', cat: 'basic', ico: '🖼', title: 'Hình ảnh', desc: 'Image' },
        { id: 'twoCol', cat: 'basic', ico: '▥', title: '2 cột', desc: 'Columns' },
        { id: 'spacer', cat: 'basic', ico: '↕', title: 'Khoảng trống', desc: 'Spacer' }
    ];

    function makeSec(type, html) {
        return { uid: uid(), type: type || 'custom', html: html };
    }

    function splitHtmlToSections(html) {
        if (!html) return [];
        var wrap = document.createElement('div');
        wrap.innerHTML = html;
        var out = [];
        var kids = wrap.children;
        if (!kids || kids.length === 0) {
            if (html.replace(/\s/g, '')) out.push(makeSec('custom', html));
            return out;
        }
        for (var i = 0; i < kids.length; i++) {
            out.push(makeSec('custom', kids[i].outerHTML));
        }
        return out;
    }

    function templatesOf() {
        return [
            {
                id: 'course', name: 'Landing khóa học', desc: 'Hero + nổi bật + giá + form',
                build: function () {
                    return [HTML.navbar, HTML.hero, HTML.features, HTML.pricing, HTML.cta, HTML.form, HTML.footer].map(function (h, i) {
                        return makeSec('tpl', h);
                    });
                }
            },
            {
                id: 'hospital', name: 'Landing bệnh viện', desc: 'Hero 2 cột + form + liên hệ',
                build: function () {
                    return [HTML.navbar, HTML.hero2, HTML.about, HTML.features, HTML.form, HTML.contact, HTML.footer].map(function (h) {
                        return makeSec('tpl', h);
                    });
                }
            },
            {
                id: 'product', name: 'Landing sản phẩm', desc: 'Hero + review + FAQ + form',
                build: function () {
                    return [HTML.navbar, HTML.hero, HTML.features, HTML.testimonial, HTML.faq, HTML.form, HTML.footer].map(function (h) {
                        return makeSec('tpl', h);
                    });
                }
            },
            {
                id: 'simple', name: 'Trang đơn giản', desc: 'Hero + form + footer',
                build: function () {
                    return [HTML.hero, HTML.form, HTML.footer].map(function (h) {
                        return makeSec('tpl', h);
                    });
                }
            }
        ];
    }

    document.addEventListener('DOMContentLoaded', function () {
        if (typeof Vue === 'undefined') {
            alert('Không tải được VueJS (CDN).');
            return;
        }

        new Vue({
            el: '#app',
            data: {
                pageId: config.pageId || 0,
                title: config.initialTitle || 'Landing Page mới',
                slug: config.initialSlug || '',
                status: false,
                saving: false,
                cat: 'all',
                sections: [],
                insertAt: null,
                selected: null,
                showTpl: false,
                widgets: WIDGETS,
                templates: templatesOf()
            },
            computed: {
                filteredWidgets: function () {
                    var c = this.cat;
                    if (c === 'all') return this.widgets;
                    return this.widgets.filter(function (w) { return w.cat === c; });
                }
            },
            watch: {
                title: function (v) {
                    if (!this.pageId || !this.slug) this.slug = slugify(v);
                }
            },
            mounted: function () {
                var self = this;
                if (!self.slug && self.title) self.slug = slugify(self.title);

                if (self.pageId > 0) {
                    self.loadPage();
                } else {
                    self.showTpl = true;
                }
            },
            methods: {
                openTemplates: function () { this.showTpl = true; },
                chooseSlot: function (at) {
                    this.insertAt = at;
                    toast('Đã chọn chỗ. Bấm widget bên trái.', true);
                },
                addWidget: function (id) {
                    var html = HTML[id];
                    if (!html) return;
                    var sec = makeSec(id, html);
                    var at = this.insertAt;
                    if (at === null) at = this.sections.length;
                    this.sections.splice(at, 0, sec);
                    this.selected = sec.uid;
                    this.insertAt = at + 1; // sẵn sàng chèn tiếp bên dưới
                    toast('Đã thêm vào đúng chỗ', true);
                },
                move: function (idx, dir) {
                    var to = idx + dir;
                    if (to < 0 || to >= this.sections.length) return;
                    var arr = this.sections;
                    var tmp = arr[idx];
                    arr.splice(idx, 1);
                    arr.splice(to, 0, tmp);
                    this.sections = arr.slice(0);
                },
                duplicate: function (idx) {
                    var src = this.sections[idx];
                    var copy = makeSec(src.type, src.html);
                    this.sections.splice(idx + 1, 0, copy);
                    this.selected = copy.uid;
                    toast('Đã nhân bản', true);
                },
                remove: function (idx) {
                    if (!confirm('Xóa khối này?')) return;
                    this.sections.splice(idx, 1);
                    this.selected = null;
                },
                onEdit: function (e) {
                    // Đồng bộ HTML sau khi user sửa chữ
                    var body = e.target;
                    if (!body || !body.classList || !body.classList.contains('sec-body')) {
                        // blur có thể từ con — tìm sec-body
                        var el = e.target;
                        while (el && el !== this.$el) {
                            if (el.classList && el.classList.contains('sec-body')) { body = el; break; }
                            el = el.parentNode;
                        }
                    }
                    if (!body || !body.classList.contains('sec-body')) return;
                    var secEl = body.parentNode;
                    var list = this.$el.querySelectorAll('.sec');
                    var idx = -1;
                    for (var i = 0; i < list.length; i++) {
                        if (list[i] === secEl) { idx = i; break; }
                    }
                    if (idx >= 0 && this.sections[idx]) {
                        this.sections[idx].html = body.innerHTML;
                    }
                },
                applyTemplate: function (t) {
                    this.sections = t.build();
                    this.insertAt = null;
                    this.showTpl = false;
                    toast('Đã áp dụng mẫu: ' + t.name, true);
                },
                buildHtml: function () {
                    // Sync từ DOM trước khi lưu (contenteditable)
                    var list = this.$el.querySelectorAll('.sec .sec-body');
                    for (var i = 0; i < list.length && i < this.sections.length; i++) {
                        this.sections[i].html = list[i].innerHTML;
                    }
                    var html = '';
                    for (var j = 0; j < this.sections.length; j++) {
                        html += this.sections[j].html;
                    }
                    return html;
                },
                buildPayload: function (publish) {
                    var html = this.buildHtml();
                    var layout = {
                        version: 2,
                        mode: 'section-stack',
                        sections: this.sections.map(function (s) {
                            return { type: s.type, html: s.html };
                        })
                    };
                    return {
                        PageID: this.pageId || 0,
                        Title: (this.title || '').trim(),
                        Slug: slugify(this.slug || this.title || ''),
                        LayoutJson: JSON.stringify(layout),
                        HtmlContent: html,
                        CssContent: '',
                        Status: !!publish
                    };
                },
                save: function (publish) {
                    var self = this;
                    var payload = self.buildPayload(publish);
                    if (!payload.Title) { toast('Nhập tên trang', false); return; }
                    if (!payload.Slug) { toast('Nhập đường dẫn (slug)', false); return; }
                    self.saving = true;
                    self.slug = payload.Slug;
                    self.status = payload.Status;
                    ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                        self.saving = false;
                        if (!res || !res.Success) {
                            toast((res && res.Message) || 'Lưu thất bại', false);
                            return;
                        }
                        if (res.Data && res.Data.PageID) {
                            self.pageId = res.Data.PageID;
                            if (window.history && window.history.replaceState) {
                                window.history.replaceState(null, '', '?id=' + self.pageId);
                            }
                        }
                        toast(publish ? 'Đã xuất bản' : 'Đã lưu', true);
                    });
                },
                saveDraft: function () { this.save(false); },
                publish: function () { this.save(true); },
                preview: function () {
                    var self = this;
                    if (!self.slug) { toast('Cần slug để xem', false); return; }
                    var payload = self.buildPayload(false);
                    self.saving = true;
                    ajaxJson(config.handlerUrl + '?action=SavePage', 'POST', payload, function (res) {
                        self.saving = false;
                        if (!res || !res.Success) {
                            toast((res && res.Message) || 'Không lưu được', false);
                            return;
                        }
                        if (res.Data && res.Data.PageID) self.pageId = res.Data.PageID;
                        window.open(config.viewUrl + '?slug=' + encodeURIComponent(self.slug) + '&preview=1', '_blank');
                    });
                },
                loadPage: function () {
                    var self = this;
                    ajaxJson(config.handlerUrl + '?action=GetPage&PageID=' + encodeURIComponent(self.pageId), 'GET', null, function (res) {
                        if (!res || !res.Success || !res.Data) {
                            self.showTpl = true;
                            return;
                        }
                        var data = res.Data;
                        self.title = data.Title || self.title;
                        self.slug = data.Slug || self.slug;
                        self.status = !!data.Status;

                        var loaded = false;
                        try {
                            if (data.LayoutJson) {
                                var layout = typeof data.LayoutJson === 'string' ? JSON.parse(data.LayoutJson) : data.LayoutJson;
                                if (layout && layout.mode === 'section-stack' && layout.sections && layout.sections.length) {
                                    self.sections = layout.sections.map(function (s) {
                                        return makeSec(s.type || 'custom', s.html || '');
                                    });
                                    loaded = true;
                                }
                            }
                        } catch (ex) { }

                        if (!loaded) {
                            self.sections = splitHtmlToSections(data.HtmlContent || '');
                        }
                        if (!self.sections.length) self.showTpl = true;
                    });
                }
            }
        });
    });
})();

