var config = window.LP_BUILDER_CONFIG || {};
var editor = null;
var toastTimer = null;
var insertMode = 'after'; // after | before | inside | end

function getSelectedTarget(ed) {
    var selected = ed.getSelected();
    if (!selected) return null;
    // Không chèn relative vào wrapper gốc
    if (selected.get && selected.get('type') === 'wrapper') return null;
    return selected;
}

function describeComponent(comp) {
    if (!comp) return 'Chưa chọn phần tử';
    var tag = '';
    try {
        tag = (comp.get('tagName') || comp.get('type') || 'element').toLowerCase();
    } catch (ex) {
        tag = 'element';
    }
    var name = '';
    try {
        var el = comp.getEl && comp.getEl();
        if (el && el.id) name = '#' + el.id;
        else if (el && el.className) {
            var cls = String(el.className).split(/\s+/)[0];
            if (cls) name = '.' + cls;
        }
    } catch (ex2) { }
    return 'Đang chọn: <' + tag + '>' + name + ' → chèn ' + modeLabel(insertMode);
}

function modeLabel(mode) {
    if (mode === 'before') return 'PHÍA TRÊN';
    if (mode === 'inside') return 'VÀO TRONG';
    if (mode === 'end') return 'CUỐI TRANG';
    return 'PHÍA DƯỚI';
}

function updateSelectedInfo(ed) {
    var info = document.getElementById('lp-selected-info');
    if (!info) return;
    var selected = getSelectedTarget(ed);
    if (!selected || insertMode === 'end') {
        info.innerHTML = insertMode === 'end'
            ? 'Chế độ: luôn thêm cuối trang'
            : 'Chưa chọn phần tử → sẽ thêm cuối trang';
        info.style.color = '#64748b';
        return;
    }
    info.innerHTML = describeComponent(selected);
    info.style.color = '#00519B';
}

/**
 * Chèn content theo vị trí đang chọn + insertMode
 */
function insertContentAt(ed, content) {
    var selected = getSelectedTarget(ed);
    var mode = insertMode;
    var added = null;

    // Không có selection hoặc mode = end → cuối body
    if (!selected || mode === 'end') {
        added = ed.addComponents(content);
        return { where: 'cuối trang', added: added };
    }

    var parent = selected.parent();
    if (!parent) {
        added = ed.addComponents(content);
        return { where: 'cuối trang', added: added };
    }

    var collection = parent.components();
    var index = typeof selected.index === 'function' ? selected.index() : collection.indexOf(selected);

    if (mode === 'before') {
        added = collection.add(content, { at: index });
        return { where: 'phía trên phần tử đang chọn', added: added };
    }

    if (mode === 'after') {
        added = collection.add(content, { at: index + 1 });
        return { where: 'phía dưới phần tử đang chọn', added: added };
    }

    if (mode === 'inside') {
        // Chỉ chèn inside nếu là container (section/div...), không phải text thuần
        var tag = (selected.get('tagName') || '').toLowerCase();
        var type = (selected.get('type') || '').toLowerCase();
        var canInside = (tag === 'section' || tag === 'div' || tag === 'header' || tag === 'footer'
            || tag === 'main' || tag === 'article' || tag === 'aside' || tag === 'nav'
            || type === 'wrapper');

        if (!canInside) {
            // fallback: after
            added = collection.add(content, { at: index + 1 });
            return { where: 'phía dưới (phần tử không chứa được bên trong)', added: added };
        }

        added = selected.append(content);
        return { where: 'bên trong phần tử đang chọn', added: added };
    }

    added = ed.addComponents(content);
    return { where: 'cuối trang', added: added };
}

function scrollToAdded(ed, added) {
    try {
        var comp = added;
        if (added && added.length) comp = added.at ? added.at(0) : added[0];
        if (!comp) return;
        if (comp.getEl) {
            var el = comp.getEl();
            if (el && el.scrollIntoView) {
                el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
        ed.select(comp);
    } catch (ex) { }
}

