function bindInsertModeButtons() {
    var buttons = document.querySelectorAll('.lp-insert-mode');
    for (var i = 0; i < buttons.length; i++) {
        buttons[i].onclick = function () {
            for (var j = 0; j < buttons.length; j++) {
                buttons[j].className = buttons[j].className.replace(/\s*active\s*/g, ' ').replace(/\s+/g, ' ').trim();
            }
            this.className = (this.className + ' active').replace(/\s+/g, ' ').trim();
            insertMode = this.getAttribute('data-mode') || 'after';
            updateSelectedInfo(editor);
            showToast('Chế độ chèn: ' + modeLabel(insertMode), true);
        };
    }
}

